import { useEffect, useState } from "react";
import { Link } from "react-router-dom";

function History() {

  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);

  // ✅ Fetch order history from backend
  useEffect(() => {
    fetch("http://localhost:5000/order-history", {
      credentials: "include"
    })
      .then(res => res.json())
      .then(data => {
        setOrders(data);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, []);

  if (loading) {
    return (
      <div style={outerStyle}>
        <h2 style={{ textAlign: "center" }}>Loading...</h2>
      </div>
    );
  }

  return (
    <div style={outerStyle}>

      <h1 style={headingStyle}>Purchased Items</h1>

      {orders.length === 0 ? (
        <h2 style={{ textAlign: "center" }}>
          No Purchased Items Yet
        </h2>
      ) : (

        orders.map((order, index) => (
          <div key={index}>

            {order.items.map((item) => (
              <div key={item.productId} style={cartBoxStyle}>

                {/* Image */}
                <div style={imageBoxStyle}>
                  <img
                    src={item.image}
                    alt={item.title}
                    style={imageStyle}
                  />
                </div>

                {/* Details */}
                <div style={{ flex: 1 }}>
                  <h2>{item.title}</h2>
                  <h3 style={{ color: "green" }}>${item.price}</h3>
                  <p style={{ fontSize: "18px" }}>
                    Quantity: {item.quantity}
                  </p>
                </div>

              </div>
            ))}

          </div>
        ))

      )}

      <div style={{ textAlign: "center", marginTop: "40px" }}>
        <Link to="/" style={backBtnStyle}>
          Continue Shopping
        </Link>
      </div>

    </div>
  );
}

//////////////////////////////////////////////////////////////
// Styles
//////////////////////////////////////////////////////////////

const outerStyle = {
  minHeight: "100vh",
  padding: "40px",
  backgroundColor: "#b7cdd6"
};

const headingStyle = {
  textAlign: "center",
  marginBottom: "40px"
};

const cartBoxStyle = {
  display: "flex",
  alignItems: "center",
  backgroundColor: "white",
  padding: "20px",
  marginBottom: "20px",
  borderRadius: "15px",
  boxShadow: "0 5px 15px rgba(0,0,0,0.1)"
};

const imageBoxStyle = {
  width: "250px",
  height: "200px",
  marginRight: "30px",
  borderRadius: "10px",
  overflow: "hidden"
};

const imageStyle = {
  width: "100%",
  height: "100%",
  objectFit: "cover"
};

const backBtnStyle = {
  padding: "10px 20px",
  backgroundColor: "blue",
  color: "white",
  textDecoration: "none",
  borderRadius: "8px"
};

export default History;
